// The member register (P1.2): exports of the register as CSV files in object
// storage, generated by the worker and deleted after 24 hours. Imports from a
// file (P1.3b): the import (a record that stays) and its staging rows
// (deleted seven days after the import ends).

import {
  EMPTY_IMPORT_COUNTS,
  MEMBER_EXPORT_COLUMNS,
  MEMBER_EXPORT_STATUSES,
  MEMBER_IMPORT_FORMATS,
  MEMBER_IMPORT_ISSUES,
  MEMBER_IMPORT_ROW_STATUSES,
  MEMBER_IMPORT_STATUSES,
  type MemberExportColumn,
  type MemberExportStatus,
  type MemberImportCounts,
  type MemberImportFormat,
  type MemberImportIssue,
  type MemberImportOptions,
  type MemberImportResolution,
  type MemberImportRowStatus,
  type MemberImportStatus,
  type RegisterFilter,
} from "@clubadmin/shared";
import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

import { clubRef, personRef } from "./clubs.ts";
import { id, oneOf, subsetOf, timestamps, tz } from "./columns.ts";
import { people } from "./people.ts";

export const memberExports = pgTable(
  "member_exports",
  {
    id: id(),
    clubId: clubRef(),
    requestedByPersonId: personRef(),
    status: text().$type<MemberExportStatus>().notNull().default("queued"),
    /** The register filter (IDs and enum values only). */
    filter: jsonb().$type<RegisterFilter>().notNull().default({}),
    columns: text().array().$type<MemberExportColumn[]>().notNull(),
    includeProtected: boolean().notNull().default(false),
    rowCount: integer(),
    /** exports/<club_id>/<id>.csv in the files bucket, once ready. */
    objectKey: text(),
    expiresAt: timestamp(tz),
    errorCode: text(),
    ...timestamps,
  },
  (t) => [
    check("member_exports_status", oneOf(t.status, MEMBER_EXPORT_STATUSES)),
    check("member_exports_columns", subsetOf(t.columns, MEMBER_EXPORT_COLUMNS)),
    check(
      "member_exports_ready",
      sql`${t.status} <> 'ready' OR (${t.objectKey} IS NOT NULL AND ${t.expiresAt} IS NOT NULL)`,
    ),
    index("member_exports_club_idx").on(t.clubId, t.createdAt),
    index("member_exports_requester_idx").on(t.requestedByPersonId, t.createdAt),
    index("member_exports_open_idx")
      .on(t.expiresAt)
      .where(sql`${t.status} IN ('queued', 'ready')`),
  ],
);

/** A column of the uploaded file as the parser saw it. */
export interface MemberImportColumn {
  index: number;
  header: string;
  sample: string | null;
  suggested: string | null;
}

export const memberImports = pgTable(
  "member_imports",
  {
    id: id(),
    clubId: clubRef(),
    createdByPersonId: personRef(),
    status: text().$type<MemberImportStatus>().notNull().default("uploaded"),
    sourceFormat: text().$type<MemberImportFormat>().notNull().default("csv"),
    /** The recognised export format (e.g. idrottonline), if any. */
    detectedSource: text(),
    /** Headers, samples and suggested fields (personal data until the rows are deleted). */
    columns: jsonb().$type<MemberImportColumn[]>().notNull().default([]),
    /** File column index → field. */
    columnMap: jsonb().$type<Record<string, string>>().notNull().default({}),
    options: jsonb().$type<MemberImportOptions>().notNull(),
    counts: jsonb().$type<MemberImportCounts>().notNull().default(EMPTY_IMPORT_COUNTS),
    /** imports/<club_id>/<id> in the files bucket until parsed. */
    objectKey: text(),
    errorCode: text(),
    confirmedByPersonId: uuid().references(() => people.id),
    confirmedAt: timestamp(tz),
    finishedAt: timestamp(tz),
    /** Staging rows and the file were deleted (seven days after the end). */
    purgedAt: timestamp(tz),
    ...timestamps,
  },
  (t) => [
    check("member_imports_status", oneOf(t.status, MEMBER_IMPORT_STATUSES)),
    check("member_imports_format", oneOf(t.sourceFormat, MEMBER_IMPORT_FORMATS)),
    index("member_imports_club_idx").on(t.clubId, t.id),
    index("member_imports_creator_idx").on(t.createdByPersonId),
    index("member_imports_confirmer_idx").on(t.confirmedByPersonId),
    index("member_imports_purge_idx")
      .on(t.updatedAt)
      .where(sql`${t.purgedAt} IS NULL AND ${t.status} IN ('done', 'failed', 'cancelled')`),
  ],
);

/** The values of a row after mapping (personal data; the identity number sealed). */
export interface MemberImportRowData {
  given: string | null;
  family: string | null;
  birthDate: string | null;
  /** Sealed with the club's data key (field encryption), never plain. */
  personalIdentityNumber: string | null;
  /** Blind index of the identity number, for duplicate checks. */
  personalIdentityNumberHash: string | null;
  gender: string | null;
  phone: string | null;
  email: string | null;
  address: { street: string; postalCode: string; city: string; country: string } | null;
  membershipType: string | null;
  startDate: string | null;
  memberNumber: number | null;
  /** Group IDs (resolved by name in the club). */
  groupIds: string[];
  groupNames: string[];
  protected: boolean;
  /** Kind on a guardian's own row (family key); such a row is not a member. */
  relation: string | null;
  guardians: {
    given: string | null;
    family: string | null;
    phone: string | null;
    email: string | null;
    kind: string;
    /** A member of the club this guardian is (name and phone match). */
    personId: string | null;
  }[];
}

export const memberImportRows = pgTable(
  "member_import_rows",
  {
    id: id(),
    importId: uuid()
      .notNull()
      .references(() => memberImports.id, { onDelete: "cascade" }),
    rowNumber: integer().notNull(),
    clubId: clubRef(),
    /** The file's cells, sealed (re-mapping without the file). */
    cells: text().notNull(),
    data: jsonb().$type<MemberImportRowData>(),
    status: text().$type<MemberImportRowStatus>().notNull().default("new"),
    issues: text().array().$type<MemberImportIssue[]>().notNull().default([]),
    familyKey: text(),
    /** The club's member this row may be or is (duplicate check). */
    matchPersonId: uuid(),
    resolution: text().$type<MemberImportResolution>(),
    skippedByUser: boolean().notNull().default(false),
    /** The person the row became (or was linked to). */
    personId: uuid(),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("member_import_rows_row_unique").on(t.importId, t.rowNumber),
    check("member_import_rows_status", oneOf(t.status, MEMBER_IMPORT_ROW_STATUSES)),
    check("member_import_rows_issues", subsetOf(t.issues, MEMBER_IMPORT_ISSUES)),
    check(
      "member_import_rows_resolution",
      sql`${t.resolution} IS NULL OR ${t.resolution} IN ('same_person', 'different_person')`,
    ),
    index("member_import_rows_status_idx").on(t.importId, t.status, t.rowNumber),
  ],
);
